import { experiment } from '@caemble/core'
import { Solid } from './geometry'
import { Steel } from './material'
export default experiment({
  lengthUnit: 'm',
  varsSchema: {},
  geometry: ({ vars }) => (
    <Solid
      id="body"
      size={[1, 0.3, 0.3]}
      position={[0.5, 0, 0]}
      materials={{ body: Steel() }}
    />
  ),
  geometryGroup: { body: ['body'] },
  surfaceGroup: {
    fixed: ['body.shape/surface/0'],
    loaded: ['body.shape/surface/1'],
  },
  recordedData: {
    modal: { task: 'modal', output: 'modal' },
    harmonic: { task: 'harmonic', output: 'harmonic' },
    buckling: { task: 'buckling', output: 'buckling' },
    transient: { task: 'transient', output: 'history' },
    transientAnimation: { task: 'transient', output: 'displacementHistory' },
    transientMesh: { task: 'transient', output: 'displacement' },
    bucklingFactor: { task: 'buckling', output: 'bucklingFactor' },
  },
})

files.material.tsx:
import { Material } from '@caemble/core'
// E: 늘어나기 어려운 정도(Pa), nu: 옆으로 수축하는 비율, density: 단위 체적의 질량.
export const Steel = () => new Material('Steel', {
  color: '#7589a0',
  models: { solid: { model: 'mechanics.isotropic-elastic@1', parameters: {
    E: { dtype: 'float64', value: 210e9, unit: 'Pa' },
    nu: { dtype: 'float64', value: 0.3, unit: '1' },
    density: { dtype: 'float64', value: 7850, unit: 'kg.m-3' },
  } } },
})

files.tasks/buckling.tsx:
import { Box, defineTask } from '@caemble/core'
// CSG surfaces retain their meaning when spatialResolution changes.
export default defineTask({
  kernel: { name: 'structural-mechanics', version: '6.1.0' },
  lengthUnit: 'm',
  config: () => ({
    parameters: {
      analysis: 'buckling',
      geometricNonlinear: false,
      relativeTolerance: {
        dtype: 'float64',
        value: 1e-8,
        quantityKind: 'Dimensionless',
        unit: '1',
      },
      maxIterations: 40,
      spatialResolution: {
        dtype: 'float64',
        value: 0.2,
        quantityKind: 'Length',
        unit: 'm',
      },
    },
    initializations: [
      {
        methodId: 'fea.body',
        target: ['experiment.geometry.body'],
        parameters: {},
      },
      {
        methodId: 'fea.spectrum',
        target: [],
        parameters: {
          frequencies: {
            dtype: 'float64',
            value: [10, 50, 100],
            quantityKind: 'Frequency',
            unit: 'Hz',
            axes: [{ length: 3 }],
          },
          modeCount: 3,
        },
      },
    ],
    boundaryConditions: [
      {
        methodId: 'fea.fixed',
        target: ['experiment.surface.fixed'],
        parameters: {
          components: {
            dtype: 'string',
            value: ['x', 'y', 'z'],
            axes: [{ length: 3 }],
          },
        },
      },
      {
        methodId: 'fea.surface-load',
        target: ['experiment.surface.loaded'],
        parameters: {
          force: {
            dtype: 'float64',
            value: [-1000, 0, 0],
            quantityKind: 'mechanics.ForceMagnitude',
            unit: 'N',
            axes: [{ length: 3 }],
          },
          moment: {
            dtype: 'float64',
            value: [0, 0, 0],
            quantityKind: 'mechanics.BendingMomentOfForce',
            unit: 'N.m',
            axes: [{ length: 3 }],
          },
          referencePoint: {
            dtype: 'float64',
            value: [1, 0, 0],
            quantityKind: 'Length',
            unit: 'm',
            axes: [{ length: 3 }],
          },
        },
      },
    ],
    outputs: [
      {
        methodId: 'fea.buckling-displacement',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [12, 6, 6], modeIndex: 1 },
        key: 'buckling',
      },
      {
        key: 'bucklingFactor',
        methodId: 'fea.buckling-factor',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [1, 1, 1], modeIndex: 1 },
      },
    ],
    exports: [],
  }),
  geometry: () => (
    <Box
      id="output-grid"
      position={[0.5, 0, 0]}
      size={[1.001, 0.30029999999999996, 0.30029999999999996]}
    />
  ),
  geometryGroup: { outputGrid: ['output-grid'] },
})

